def solve(inputs: dict) -> float:
    """Return the numerator of the finite simple continued fraction terms."""
    terms = inputs.get('terms', inputs.get('coefficients', inputs.get('a')))
    if terms is None:
        for key, value in inputs.items():
            if isinstance(value, (list, tuple)):
                terms = value
                break
    if terms is None or len(terms) == 0:
        raise ValueError('Expected a nonempty sequence of continued-fraction terms')
    # Standard recurrence p_-2=0, p_-1=1; after consuming a_0,
    # p_0=a_0, equivalent to the recurrence stated in the problem.
    p_prevprev, p_prev = 0, 1
    for term in terms:
        p_prevprev, p_prev = p_prev, int(term) * p_prev + p_prevprev
    return p_prev

